import XCTest

@MainActor final class AchievementDeliveryJourneyTests:XCTestCase {
 private func tap(_ id:String,_ app:XCUIApplication){let b=app.buttons[id];XCTAssertTrue(b.waitForExistence(timeout:15),id);for _ in 0..<8 where !b.isHittable{app.swipeUp(velocity:.slow)};XCTAssertTrue(b.isHittable,id);b.tap()}
 private func photo(_ name:String,_ app:XCUIApplication){let a=XCTAttachment(screenshot:app.screenshot());a.name=name;a.lifetime = .keepAlways;add(a)}
 func testRealEmulatorReviewAwardTakesFallbackAndTutorFooterThenRestoresControlsWithoutAnotherReward()async throws{
  let gate=LocalMembershipServer(),relay=LocalNostrRelay();defer{gate.stop();relay.stop()};gate.status(["allow":true]);try await gate.start();try await relay.start{frame,c in if frame.first as?String=="REQ",let sub=frame[1]as?String{relay.send(["EOSE",sub],to:c)}}
  continueAfterFailure=false;let app=XCUIApplication();app.launchEnvironment=["PIYALI_OFFLINE_TESTS":"1","PIYALI_TEST_IDENTITY_SCOPE":UUID().uuidString,"PIYALI_ENTRY_INITIAL_LANGUAGE":"en","PIYALI_ENTRY_INITIAL_THEME":"light","PIYALI_SETTINGS_FIXTURE":"1","PIYALI_FLASHCARD_FIXTURE":"1","PIYALI_HEADLINE_FIXTURE":"failure","PIYALI_ACHIEVEMENT_DELIVERY_UI":"1","PIYALI_ACHIEVEMENT_RETRY_UI":"1","PIYALI_FIRESTORE_EMULATOR_PORT":"8330","PIYALI_ACHIEVEMENT_RETRY_RELAY":relay.url,"PIYALI_ACHIEVEMENT_RETRY_GATE":gate.url+"/status"];app.launchArguments=["-AppleLanguages","(en)","-AppleLocale","en_US"];app.launch();handleInitialPaperPencil(app);let name=app.textFields["entryName"];XCTAssertTrue(name.waitForExistence(timeout:15));name.tap();name.typeText("Award Learner");tap("entryKeyboardDone",app);tap("createAccount",app);handleInitialPaperPencil(app);tap("onboardingPractice",app);let spanish=app.descendants(matching:.any).matching(NSPredicate(format:"label == %@","Spanish")).allElementsBoundByIndex.first{$0.isHittable};XCTAssertNotNil(spanish);spanish?.tap();tap("startLearning",app)
  tap("productMenu",app);tap("productModeMenu",app);tap("productMode-cards",app);tap("flashcardTile-pre-a1-people-1",app);let answer=app.textFields["flashcardAnswer"];XCTAssertTrue(answer.waitForExistence(timeout:8));answer.tap();answer.typeText("mamá\n");XCTAssertTrue(app.staticTexts["flashcardReward"].waitForExistence(timeout:15));XCTAssertTrue(app.staticTexts["flashcardReward"].label.contains("6"));tap("flashcardRate-hard",app)
  XCTAssertTrue(app.buttons["achievementContinue"].waitForExistence(timeout:25));photo("Native confirmed award fallback after review",app);tap("productMenu",app);tap("productModeMenu",app);tap("productMode-tutor",app);XCTAssertTrue(app.buttons["achievementContinue"].waitForExistence(timeout:15));XCTAssertFalse(app.buttons["tutorStart"].exists && app.buttons["tutorStart"].isHittable);photo("Native award owns Tutor footer",app);tap("achievementContinue",app);XCTAssertTrue(app.buttons["tutorStart"].waitForExistence(timeout:15));XCTAssertFalse(app.buttons["achievementContinue"].exists);photo("Native Tutor controls restored after award",app)
  app.terminate();app.launch();handleInitialPaperPencil(app);XCTAssertTrue(app.buttons["productMenu"].waitForExistence(timeout:15));XCTAssertFalse(app.buttons["achievementContinue"].exists);for _ in 0..<6 where !app.buttons["focusAchievements"].isHittable{app.swipeUp(velocity:.slow)};tap("focusAchievements",app);XCTAssertTrue(app.staticTexts["achievementCollectionCount"].waitForExistence(timeout:10));XCTAssertEqual(app.staticTexts["achievementCollectionCount"].label,"1 of 76 collected");photo("Native earned award restored without celebration replay",app)
 }
}
